@spec tv_fx_region_spec  src=tests/specs/tv_fx_region_spec.lua  loc=1260  cases=64
@exercises dataStore (h.ds), trackerManager (h.tm), midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), clipboard (h.clipboard)
@surface   ds:assign, tm:rebuild, ds:get, tm:addEvent, tm:flush, fm:dump, vm:setGridSize, vm:ppqToRow, ec:setPos, vm:fxHostForEdit, vm:noteFx, vm:setNoteFx, vm:removeFxStage, vm:addFxStage, vm:setFxField, ec:setSelection, vm:rowToPPQ, vm:fxHostAtCursor, cmgr:invoke, tm:getChannel, vm:editEvent, tm:subscribe, ec:row, ec:extendTo, clipboard:collect, vm:ghostOverlay
@harness   mk

# Intent
  Track B (note macros v2): the fx-region column + Super-X addressing. A region
  renders as a tailed kind-badge in a per-channel fx column, and the v1 note-FX
  editor addresses it by uuid. see design/note-macros-v2.md § Authoring and editing the fx

# Helpers
  @fn injectRegion(h, over)  @ 24-29
  @fn fxColFor(h, chan)  @ 31-35
  @fn region(h, uuid)  @ 37-41
  @fn noteColIdx(h, chan, lane)  @ 43-47
  @fn addNote(h)  @ 49-53
  @fn authoredUuid(h)  @ 55-57
  @fn authoredPitches(h)  @ 61-68
      -- Pitches still sounding on the take (non-derived). Empty once a replace region has
      -- parked the covered chord off-take.

# Cases
  @case 'a region materialises a per-channel fx column with a badge + tail'  [harness]  @ 75-87
  @case 'a chain stacks its glyphs down the region rows in series order'  [harness]  @ 91-104
  @case 'a bypassed stage carries its flag down the stack'  [harness]  @ 108-118
  @case 'a chain longer than the region clips at the last row and marks it'  [harness]  @ 122-132
  @case 'a one-row region gives the clip mark the badge row'  [harness]  @ 136-144
  @case 'no region -> no fx column'  [harness]  @ 148-154
  @case 'an empty-fx region renders no column (it is an inert husk)'  [harness]  @ 158-164
  @case 'two overlapping regions pack into separate fx columns, each addressable'  [harness]  @ 170-198
  @case 'two disjoint regions share one fx column (packed into lane 1)'  [harness]  @ 202-214
  @case 'replace region: a parked note still renders in its note column'  [harness]  @ 220-232
  @case 'replace region: a parked cc still renders in its cc column'  [harness]  @ 236-259
  @case 'noteFx resolves a region uuid to its fx list'  [harness]  @ 265-270
  @case 'setNoteFx writes a region fx list back to ds'  [harness]  @ 274-280
  @case 'setNoteFx REMOVE deletes the region (a region is its fx)'  [harness]  @ 284-290
  @case 'region fx: deselecting the last kind keeps a husk the editor can repopulate'  [harness]  @ 294-304
  @case 'setFxField edits one region fx field, leaving the region'  [harness]  @ 308-314
  @case 'fxHostForEdit: caret on an fx cell returns the region uuid'  [harness]  @ 320-328
  @case 'fxHostForEdit: a selection mints a replace region over its span'  [harness]  @ 332-346
  @case 'fxHostAtCursor: a selection does not mint -- cursor movement has no side effect'  [harness]  @ 350-358
  @case 'fxHostAtCursor: caret anywhere in an fx region returns its uuid, nil past the tail'  [harness]  @ 362-375
  @case 'fxHostForEdit: off a note with no selection is nil; on a note, its uuid (v1)'  [harness]  @ 379-389
  @case 'parked note: a pitch nudge edits the off-take stash and re-renders, still parked'  [harness]  @ 395-409
  @case 'parked note: delete removes it from the stash and does not restore it when the window moves off'  [harness]  @ 413-424
  @case 'parked add: typing a note into a replace window stashes a logical spec, off the take'  [harness]  @ 428-442
  @case 'parked move-out: nudging a parked note past the window end restores it to the take'  [harness]  @ 446-459
  @case 'parked cc: a value nudge edits the off-take cc stash; delete removes it'  [harness]  @ 463-495
  @case 'parked pb: a value nudge edits the off-take pb stash; delete removes it'  [harness]  @ 499-535
  @case 'multi-select spanning a parked note and a take note: both edit under one rebuild'  [harness]  @ 539-560
  @case 'fx noteOff truncates the region tail to the cursor row'  [harness]  @ 566-578
  @case 'fx noteOff finds the right region in its lane when cells are in storage, not ppq, order'  [harness]  @ 582-596
  @case 'fx noteOff past the region tail grows it to the cursor row'  [harness]  @ 600-609
  @case 'fx noteOff on the onset row is a no-op (deletion is the delete verb, not noteOff)'  [harness]  @ 613-624
  @case 'fx noteOff on the window end row re-opens it to the pattern length'  [harness]  @ 628-638
  @case 'fx growNote / shrinkNote resize the region from its end'  [harness]  @ 642-653
  @case 'fx nudgeForward shifts the whole window and the caret follows'  [harness]  @ 657-669
  @case 'fx nudge keeps the moved region in its lane; the newly-overlapped sibling displaces right'  [harness]  @ 673-695
  @case 'fx nudge of an already-overlapping region keeps its own higher lane (no reorder)'  [harness]  @ 699-718
  @case 'fx nudge that makes an overlap disjoint tracks the caret across the column merge'  [harness]  @ 722-742
  @case 'fx window edit on a disjoint region does not churn storage order'  [harness]  @ 746-762
  @case 'fx nudgeBack refuses at the top grid edge (window unchanged)'  [harness]  @ 766-777
  @case 'fx eventShiftLeft swaps the region one lane left, flipping storage precedence'  [harness]  @ 783-807
  @case 'fx eventShiftRight swaps the region one lane right (the inverse move)'  [harness]  @ 811-826
  @case 'fx eventShift is a no-op at the grid edge (lone region, nothing beside it)'  [harness]  @ 830-842
  @case 'fx eventShift no-ops when the adjacent lane is empty at the cursor row'  [harness]  @ 846-861
  @case 'parked note: noteOff shortens its tail in the stash, stays parked'  [harness]  @ 867-880
  @case 'parked note: a time nudge within the window retimes the stash, stays parked'  [harness]  @ 884-897
  @case 'fx copy captures a region by onset; the whole window rides, tail spilling past the band'  [harness]  @ 903-921
  @case 'fx copy skips a region that only passes through the band (onset above it)'  [harness]  @ 925-934
  @case 'fx copy + paste stacks a duplicate region at the cursor row, original intact'  [harness]  @ 938-958
  @case 'fx delete removes the region under the caret'  [harness]  @ 962-971
  @case 'fx deleteSel drops every region the rectangle catches (onset in band), sparing the rest'  [harness]  @ 975-992
  @case 'fx freeze promotes the region output to authored notes and drops the region'  [harness]  @ 998-1010
  @case 'fx freeze converts an fx-carrying note at the caret'  [harness]  @ 1014-1026
  @case 'fx freeze declines on a plain note (no chain to freeze)'  [harness]  @ 1030-1040
  @case 'fx freeze: a refused freeze opens no undo block; an eligible one opens exactly one'  [harness]  @ 1047-1084
  @case 'ghostOverlay: no host under the caret returns nil, before any window query'  [harness]  @ 1090-1099
  @case 'ghostOverlay: a host lights its derived onsets on the lane column, with pitch and vel'  [harness]  @ 1103-1128
  @case 'ghostOverlay: a host whose onsets lie outside the window answers empty, not nil'  [harness]  @ 1132-1144
  @case 'ghostOverlay: a row carrying a real cell still reports its ghost -- precedence is the draw arm\'s'  [harness]  @ 1148-1160
  @case 'ghostOverlay: the window is the viewport -- onsets below it are absent'  [harness]  @ 1164-1179
  @case 'ghostOverlay: a polyphonic chain\'s ghosts land on the provisional lane columns'  [harness]  @ 1184-1199
  @case 'ghostOverlay: a region host suppresses the parked chord it replaced, cells intact'  [harness]  @ 1205-1224
  @case 'ghostOverlay: the host\'s own parked cell stays visible'  [harness]  @ 1228-1245
  @case 'ghostOverlay: nothing on the take is ever suppressed'  [harness]  @ 1249-1258

